const r = $input.first().json;
const b = r.body || {};
const code = r.statusCode;

// 409 = ya hay un ciclo corriendo. Es normal, no alarma.
if (code === 409) {
  return [{ json: { alerta: false, texto: 'ciclo solapado, se omite' } }];
}

return [{ json: {
  alerta: true,
  texto: `🚨 El ciclo falló (HTTP ${code})\n${JSON.stringify(b).slice(0, 400)}`
}}];

const s = $input.first().json.body || {};
const n = s.neurons ?? 0;

const texto = [
  `✅ Ciclo completado`,
  `vistos: ${s.vistos ?? 0}  ·  órdenes: ${s.ordenes ?? 0}`,
  `vetados: ${s.vetados ?? 0}  ·  pass: ${s.pass ?? 0}`,
  `neurons: ${n}  ·  ${s.duracion_s ?? 0}s`
].join('\n');

// Solo avisa si hubo ordenes o si el presupuesto va alto.
const alerta = (s.ordenes ?? 0) > 0;
return [{ json: { alerta, texto } }];

const b = $input.first().json.body || {};
const n = b.resueltos ?? 0;
if (n === 0) return [{ json: { alerta: false, texto: 'nada resolvió' } }];

const texto = [
  `📊 ${n} mercado(s) resolvieron`,
  `Brier: ${b.brier ?? '—'}  vs mercado ${b.brier_market ?? '—'}`,
  `skill: ${b.skill_vs_market ?? '—'}`,
  `PnL: $${b.pnl_usd ?? 0}`
].join('\n');
return [{ json: { alerta: true, texto } }];

const r = $input.first().json;
const n = r.n_resolved ?? 0;
const bss = r.skill_vs_market;

// El criterio que decide si el piloto vive. Debajo de 30 resoluciones
// el numero es ruido y no se reporta como veredicto.
let veredicto;
if (n < 30) {
  veredicto = `⏳ ${n}/30 resoluciones — aún no hay señal`;
} else if (bss > 0) {
  veredicto = `✅ HAY EDGE — skill ${bss} sobre el mercado`;
} else {
  veredicto = `🔴 EL MERCADO GANA — skill ${bss}. Considera apagar.`;
}

const texto = [
  `📈 Reporte diario`,
  veredicto,
  `Brier ${r.brier} vs mercado ${r.brier_market}`,
  `le ganamos al precio en ${Math.round((r.beat_market_rate ?? 0) * 100)}% de los casos`,
  `PnL acumulado: $${r.pnl_usd ?? 0}`
].join('\n');

return [{ json: { alerta: true, texto, escribir_vault: n >= 30 } }];

const r = $input.first().json;
const s = r.body || {};
const code = r.statusCode;

if (code === 503 || s.killed) {
  return [{ json: { alerta: true, texto:
    `🚨 KILL SWITCH ACTIVO\n${s.kill_reason || 'sin motivo'}\n\nNo se opera hasta que lo desarmes a mano.` }}];
}
if (code !== 200) {
  return [{ json: { alerta: true, texto: `🚨 El agente no responde (HTTP ${code})` }}];
}

// Aviso de presupuesto: al 85% conviene saberlo antes de que se agote.
const b = s.budget || {};
if ((b.pct_consumido ?? 0) > 85) {
  return [{ json: { alerta: true, texto:
    `⚠️ Presupuesto al ${b.pct_consumido}% — quedan ${b.neurons_disponibles} neurons y ${b.gemini_restantes} llamadas a Gemini` }}];
}

return [{ json: { alerta: false, texto: 'todo bien' } }];
